arguments.command:
$content = Get-Content "N:\noa\specs\001-noa-seed-foundation\tasks.md" -Raw
$phases = @{}
$currentPhase = "Unknown"

$content -split "`n" | ForEach-Object {
    if ($_ -match '^## (Phase .+)$') {
        $currentPhase = $matches[1]
        if (-not $phases.ContainsKey($currentPhase)) {
            $phases[$currentPhase] = @{ Complete = 0; Incomplete = 0 }
        }
    }
    elseif ($_ -match '^- \[[xX]\] ') {
        $phases[$currentPhase].Complete++
    }
    elseif ($_ -match '^- \[ \] ') {
        $phases[$currentPhase].Incomplete++
    }
}

Write-Host "`n=== TASK COMPLETION STATUS ===" -ForegroundColor Cyan
Write-Host "`nTotal Completed: 796 tasks" -ForegroundColor Green
Write-Host "Total Incomplete: 362 tasks" -ForegroundColor Yellow
Write-Host "Overall Progress: $([math]::Round(796/(796+362)*100, 1))%" -ForegroundColor Cyan

Write-Host "`n=== BY PHASE ===" -ForegroundColor Cyan
$phases.GetEnumerator() | Sort-Object Name | ForEach-Object {
    $phase = $_.Key
    $stats = $_.Value
    $total = $stats.Complete + $stats.Incomplete
    if ($total -gt 0) {
        $pct = [math]::Round($stats.Complete / $total * 100, 1)
        $status = if ($stats.Incomplete -eq 0) { "✅ COMPLETE" } else { "⚠️  IN PROGRESS" }
        Write-Host "`n$phase $status" -ForegroundColor $(if ($stats.Incomplete -eq 0) { "Green" } else { "Yellow" })
        Write-Host "  Completed: $($stats.Complete)/$total ($pct%)"
        if ($stats.Incomplete -gt 0) {
            Write-Host "  Remaining: $($stats.Incomplete)" -ForegroundColor Yellow
        }
    }
}

